Chapter.Code:
template<typename T>
T PerspectiveInterpolate(
    const T& a0,
    const T& a1,
    const T& a2,
    float w0,
    float w1,
    float w2,
    float lambda0,
    float lambda1,
    float lambda2)
{
    // Interpolate reciprocal homogeneous W.
    const float reciprocalW =
        lambda0 / w0 +
        lambda1 / w1 +
        lambda2 / w2;

    // Interpolate attribute/W in screen space.
    const T numerator =
        a0 * (lambda0 / w0) +
        a1 * (lambda1 / w1) +
        a2 * (lambda2 / w2);

    // Recover the original varying.
    return numerator / reciprocalW;
}

